<?php
/** Excel: formulas and references, essential functions, lookups with XLOOKUP, tables, pivot tables and charts. */

return [
    'id' => 'excel', 'family' => 'excel', 'after' => null,
    'title' => L('Excel', 'Excel'), 'short' => L('Excel', 'Excel'), 'level' => L('Base', 'Basics'),
    'desc' => L('Il foglio di calcolo usato in ogni ufficio: formule e riferimenti, funzioni essenziali, CERCA.X, tabelle, tabelle pivot e grafici. Con i nomi italiani e inglesi delle funzioni.', 'The spreadsheet used in every office: formulas and references, essential functions, XLOOKUP, tables, pivot tables and charts. With Italian and English function names.'),
    'lessons' => [
        lesson('formulas', L('Formule e riferimenti', 'Formulas and references'), [
            P('Una **formula** inizia sempre con `=` e calcola usando valori e **riferimenti** ad altre celle (`A1`, `B2:B10`). Se cambi un valore, tutte le formule che lo usano si aggiornano da sole.', 'A **formula** always starts with `=` and calculates using values and **references** to other cells (`A1`, `B2:B10`). If you change a value, every formula using it updates by itself.'),
            C('=B2*C2            prezzo × quantità
=B2*(1+$F$1)      prezzo con l’IVA scritta nella cella F1
=SUM(D2:D20)      somma di un intervallo     (italiano: =SOMMA(D2:D20))', 'text'),
            P('Quando copi una formula, i riferimenti **relativi** (`B2`) si spostano insieme a lei; quelli **assoluti** (`$F$1`, con il dollaro) restano fissi. Si alterna tra i due con **F4**. Attenzione: nell’Excel italiano i nomi delle funzioni sono tradotti (`SOMMA`, `SE`, `MEDIA`) e gli argomenti si separano con il **punto e virgola**.', 'When you copy a formula, **relative** references (`B2`) move with it; **absolute** ones (`$F$1`, with the dollar) stay fixed. You toggle between them with **F4**. Beware: in Italian Excel function names are translated (`SOMMA`, `SE`, `MEDIA`) and arguments are separated by **semicolons**.'),
        ], [
            Q('f1', L('Con che carattere inizia una formula?', 'What character does a formula start with?'), ['=', '+', '#', '$'], 0, L('Sempre.', 'Always.')),
            Q('f2', L('Che cosa fa il dollaro in `$F$1`?', 'What does the dollar in `$F$1` do?'), [L('Rende fisso il riferimento quando copi', 'Keeps the reference fixed when copying'), L('Indica una valuta', 'Indicates a currency'), L('Cancella la cella', 'Clears the cell'), L('Somma la colonna', 'Sums the column')], 0, L('Riferimento assoluto.', 'Absolute reference.')),
            Q('f3', L('Come si separano gli argomenti nell’Excel italiano?', 'How are arguments separated in Italian Excel?'), [L('Con il punto e virgola', 'With semicolons'), L('Con la virgola sempre', 'Always with commas'), L('Con gli spazi', 'With spaces'), L('Con i trattini', 'With dashes')], 0, L('=SOMMA(A1;A2)', '=SOMMA(A1;A2)')),
        ], task('excel', L('Scrivi la formula per la cella E2 che calcola il totale di `B2` (prezzo) per `C2` (quantità) più l’IVA della cella fissa `F1`: `=B2*C2*(1+$F$1)`.', 'Write the formula for cell E2 computing `B2` (price) times `C2` (quantity) plus the VAT in fixed cell `F1`: `=B2*C2*(1+$F$1)`.'), '', [re('^\s*=\s*B2\s*\*\s*C2\s*\*\s*\(\s*1\s*\+\s*\$F\$1\s*\)\s*$|^\s*=\s*C2\s*\*\s*B2\s*\*\s*\(\s*1\s*\+\s*\$F\$1\s*\)\s*$', L('La formula con riferimento assoluto', 'The formula with absolute reference'))], '', '=B2*C2*(1+$F$1)'), [
            dMatch(pMatch(), [['=', L('Inizio della formula', 'Formula start')], ['A1', L('Riferimento relativo', 'Relative reference')], ['$A$1', L('Riferimento assoluto', 'Absolute reference')], ['B2:B10', L('Intervallo', 'Range')], ['F4', L('Alterna i riferimenti', 'Toggles references')]], L('Le basi delle formule.', 'Formula basics.')),
            dFlash(pFlash(), [[L('Le formule si aggiornano quando cambiano i valori', 'Formulas update when values change'), true], [L('Un riferimento relativo resta fisso quando copi', 'A relative reference stays fixed when copying'), false], [L('Nell’Excel italiano SUM si chiama SOMMA', 'In Italian Excel SUM is called SOMMA'), true], [L('Una formula può iniziare senza =', 'A formula can start without ='), false]], L('Calcolare con le celle.', 'Calculating with cells.')),
        ]),
        lesson('functions', L('Funzioni essenziali', 'Essential functions'), [
            P('Le funzioni più usate: `SUM`/`SOMMA`, `AVERAGE`/`MEDIA`, `COUNT`/`CONTA.NUMERI`, `MIN`, `MAX`, `ROUND`/`ARROTONDA`. Con `IF`/`SE` fai una scelta; con `SUMIFS`/`SOMMA.PIÙ.SE` e `COUNTIFS`/`CONTA.PIÙ.SE` sommi o conti solo le righe che rispettano dei criteri.', 'The most used functions: `SUM`/`SOMMA`, `AVERAGE`/`MEDIA`, `COUNT`/`CONTA.NUMERI`, `MIN`, `MAX`, `ROUND`/`ARROTONDA`. With `IF`/`SE` you make a choice; with `SUMIFS`/`SOMMA.PIÙ.SE` and `COUNTIFS`/`CONTA.PIÙ.SE` you sum or count only rows meeting criteria.'),
            C('=IF(D2>=100, "Spedizione gratis", "Spedizione 4,90 €")
=SE(D2>=100; "Spedizione gratis"; "Spedizione 4,90 €")         (italiano)

=SUMIFS(D:D, B:B, "Nord", C:C, ">=2026-01-01")
=SOMMA.PIÙ.SE(D:D; B:B; "Nord"; C:C; ">=2026-01-01")           (italiano)

=COUNTIFS(E:E, "pagato")          quanti ordini pagati', 'text'),
            P('Le funzioni si possono annidare (`=ROUND(AVERAGE(B2:B10), 1)`). Se compare un errore: `#DIV/0!` divisione per zero, `#N/A` valore non trovato, `#NAME?` nome di funzione sbagliato (spesso perché hai usato il nome inglese nell’Excel italiano). `IFERROR`/`SE.ERRORE` sostituisce l’errore con un valore.', 'Functions can be nested (`=ROUND(AVERAGE(B2:B10), 1)`). If an error shows: `#DIV/0!` division by zero, `#N/A` value not found, `#NAME?` wrong function name (often because you used the English name in Italian Excel). `IFERROR`/`SE.ERRORE` replaces the error with a value.'),
        ], [
            Q('n1', L('Che cosa fa `SE` / `IF`?', 'What does `IF` / `SE` do?'), [L('Restituisce un valore o un altro secondo una condizione', 'Returns one value or another based on a condition'), L('Somma una colonna', 'Sums a column'), L('Ordina i dati', 'Sorts data'), L('Crea un grafico', 'Creates a chart')], 0, L('Condizione, se vero, se falso.', 'Condition, if true, if false.')),
            Q('n2', L('Quale funzione somma solo le righe che rispettano dei criteri?', 'Which function sums only rows meeting criteria?'), ['SUMIFS / SOMMA.PIÙ.SE', 'SUM / SOMMA', 'COUNT / CONTA.NUMERI', 'MAX'], 0, L('Più criteri insieme.', 'Several criteria at once.')),
            Q('n3', L('Che cosa indica l’errore `#NAME?`?', 'What does the `#NAME?` error mean?'), [L('Nome di funzione non riconosciuto', 'Function name not recognised'), L('Divisione per zero', 'Division by zero'), L('Valore non trovato', 'Value not found'), L('Foglio pieno', 'Sheet full')], 0, L('Spesso inglese nell’Excel italiano.', 'Often English names in Italian Excel.')),
        ], task('excel', L('Scrivi una formula che in F2 mostri `"Promosso"` se `E2` è maggiore o uguale a 18, altrimenti `"Rimandato"` (con `IF` e la virgola o `SE` e il punto e virgola).', 'Write a formula showing in F2 `"Promosso"` if `E2` is at least 18, otherwise `"Rimandato"` (with `IF` and commas or `SE` and semicolons).'), '', [re('^\s*=\s*(IF|SE)\s*\(\s*E2\s*>=\s*18\s*[,;]\s*"Promosso"\s*[,;]\s*"Rimandato"\s*\)\s*$', L('La condizione giusta', 'The right condition'))], '', '=SE(E2>=18; "Promosso"; "Rimandato")'), [
            dMatch(pMatch(), [['SUM', 'SOMMA'], ['AVERAGE', 'MEDIA'], ['IF', 'SE'], ['SUMIFS', 'SOMMA.PIÙ.SE'], ['IFERROR', 'SE.ERRORE']], L('Inglese e italiano.', 'English and Italian.')),
            dBug(pBug(), ['=MEDIA(B2:B10)', '=SOMMA(C2:C10)', '=SE(D2>100, "alto", "basso")'], 2, '=SE(D2>100; "alto"; "basso")', L('Nell’Excel italiano si separa con il punto e virgola.', 'In Italian Excel you separate with semicolons.')),
        ]),
        lesson('lookup', L('Cercare dati: CERCA.X', 'Looking up data: XLOOKUP'), [
            P('Per prendere un dato da un’altra tabella (il prezzo di un codice prodotto, il nome di un cliente) si usa **`XLOOKUP`** (in italiano **`CERCA.X`**): cerca un valore in una colonna e restituisce il valore corrispondente di un’altra. Sostituisce il vecchio `VLOOKUP`/`CERCA.VERT`, più fragile.', 'To fetch data from another table (a product code’s price, a customer’s name) you use **`XLOOKUP`** (Italian **`CERCA.X`**): it looks up a value in one column and returns the matching value from another. It replaces the old, more fragile `VLOOKUP`/`CERCA.VERT`.'),
            C('=XLOOKUP(A2, Listino!A:A, Listino!C:C, "non trovato")
=CERCA.X(A2; Listino!A:A; Listino!C:C; "non trovato")      (italiano)

    cerca il codice di A2 nella colonna A del foglio Listino
    e restituisce il prezzo dalla colonna C', 'text'),
            P('Rispetto a `CERCA.VERT`, `CERCA.X` cerca in qualsiasi direzione, non si rompe se inserisci colonne e cerca il valore esatto di base. Il quarto argomento evita l’errore `#N/A` quando il valore non c’è.', 'Compared to `VLOOKUP`, `XLOOKUP` searches in any direction, does not break if you insert columns and looks for the exact value by default. The fourth argument avoids the `#N/A` error when the value is missing.'),
        ], [
            Q('l1', L('Che cosa fa CERCA.X / XLOOKUP?', 'What does XLOOKUP / CERCA.X do?'), [L('Cerca un valore e restituisce il corrispondente di un’altra colonna', 'Looks up a value and returns the matching one from another column'), L('Ordina i dati', 'Sorts data'), L('Cancella i doppioni', 'Removes duplicates'), L('Crea una tabella pivot', 'Creates a pivot table')], 0, L('Come una piccola query.', 'Like a small query.')),
            Q('l2', L('Perché preferirlo a CERCA.VERT?', 'Why prefer it to VLOOKUP?'), [L('Non si rompe inserendo colonne e cerca in ogni direzione', 'It does not break on inserted columns and searches any direction'), L('È più vecchio', 'It is older'), L('Non c’è differenza', 'There is no difference'), L('Funziona solo su Mac', 'It only works on Mac')], 0, L('Più robusto.', 'More robust.')),
            Q('l3', L('A che cosa serve il quarto argomento?', 'What is the fourth argument for?'), [L('Il valore da mostrare se non trova niente', 'The value shown if nothing is found'), L('Il colore della cella', 'The cell colour'), L('Il numero di righe', 'The number of rows'), L('Il nome del foglio', 'The sheet name')], 0, L('Niente #N/A.', 'No #N/A.')),
        ], task('excel', L('Scrivi una formula `CERCA.X` (o `XLOOKUP`) che cerca il codice in `A2` nella colonna `Clienti!A:A` e restituisce l’email da `Clienti!D:D`, con `"assente"` se non lo trova.', 'Write an `XLOOKUP` (or `CERCA.X`) formula looking up the code in `A2` in column `Clienti!A:A` and returning the email from `Clienti!D:D`, with `"assente"` if not found.'), '', [re('^\s*=\s*(XLOOKUP|CERCA\.X)\s*\(\s*A2\s*[,;]\s*Clienti!A:A\s*[,;]\s*Clienti!D:D\s*[,;]\s*"assente"\s*\)\s*$', L('La ricerca completa', 'The complete lookup'))], '', '=CERCA.X(A2; Clienti!A:A; Clienti!D:D; "assente")'), [
            dOrder(pSort(), ['=CERCA.X(', 'A2;', 'Listino!A:A;', 'Listino!C:C;', '"non trovato")'], L('Cosa cerchi, dove, cosa restituire, se manca.', 'What you look for, where, what to return, if missing.')),
            dMatch(pMatch(), [['XLOOKUP', 'CERCA.X'], ['VLOOKUP', 'CERCA.VERT'], ['#N/A', L('Valore non trovato', 'Value not found')], ['Listino!A:A', L('Colonna di un altro foglio', 'Column on another sheet')]], L('Cercare tra tabelle.', 'Looking up across tables.')),
        ]),
        lesson('pivot', L('Tabelle, pivot e grafici', 'Tables, pivots and charts'), [
            P('Trasforma i dati in una **tabella** (Inserisci → Tabella, o Ctrl+T): ottieni filtri, righe colorate, totali e formule che si estendono da sole. Una regola d’oro: una riga per record, una colonna per campo, intestazioni chiare, niente celle unite.', 'Turn data into a **table** (Insert → Table, or Ctrl+T): you get filters, banded rows, totals and formulas that extend by themselves. A golden rule: one row per record, one column per field, clear headers, no merged cells.'),
            P('Una **tabella pivot** riassume migliaia di righe in pochi secondi: trascini i campi in Righe (es. Regione), Colonne (es. Anno) e Valori (es. somma delle Vendite) e Excel calcola i totali per ogni combinazione. Da una pivot si crea un **grafico pivot** che si aggiorna con i filtri.', 'A **pivot table** summarises thousands of rows in seconds: you drag fields into Rows (e.g. Region), Columns (e.g. Year) and Values (e.g. sum of Sales) and Excel computes totals for every combination. From a pivot you create a **pivot chart** that updates with the filters.'),
            Tip('Scegli il grafico in base alla domanda: barre per confrontare categorie, linee per l’andamento nel tempo, torta solo per poche parti di un totale.', 'Pick the chart by the question: bars to compare categories, lines for trends over time, pie only for a few parts of a whole.'),
        ], [
            Q('p1', L('Che cosa fa una tabella pivot?', 'What does a pivot table do?'), [L('Riassume i dati per categorie', 'Summarises data by categories'), L('Disegna immagini', 'Draws images'), L('Cancella righe', 'Deletes rows'), L('Invia email', 'Sends email')], 0, L('Righe, colonne, valori.', 'Rows, columns, values.')),
            Q('p2', L('Quale grafico per l’andamento nel tempo?', 'Which chart for trends over time?'), [L('A linee', 'Line'), L('A torta', 'Pie'), L('A dispersione 3D', '3D scatter'), L('Nessuno', 'None')], 0, L('Le barre confrontano categorie.', 'Bars compare categories.')),
            Q('p3', L('Che cosa evitare nei dati da analizzare?', 'What should you avoid in data to analyse?'), [L('Le celle unite', 'Merged cells'), L('Le intestazioni', 'Headers'), L('Una riga per record', 'One row per record'), L('I numeri', 'Numbers')], 0, L('Rompono filtri e pivot.', 'They break filters and pivots.')),
        ], task('text', L('Descrivi una tabella pivot per vedere le vendite totali per regione e anno, una riga per area come `Righe: …`, `Colonne: …`, `Valori: …`.', 'Describe a pivot table showing total sales by region and year, one line per area as `Rows: …`, `Columns: …`, `Values: …`.'), "Righe: \nColonne: \nValori: ", [re('^(Righe|Rows):\s*(Regione|Region)', L('Regione nelle righe', 'Region in rows')), re('^(Colonne|Columns):\s*(Anno|Year)', L('Anno nelle colonne', 'Year in columns')), re('^(Valori|Values):.*(Somma|Sum|Totale|Total).*(Vendite|Sales)|^(Valori|Values):.*(Vendite|Sales).*(somma|sum)', L('Somma delle vendite nei valori', 'Sum of sales in values'))], '', "Righe: Regione\nColonne: Anno\nValori: Somma di Vendite"), [
            dMatch(pMatch(), [['Ctrl+T', L('Crea una tabella', 'Creates a table')], [L('Pivot: Righe', 'Pivot: Rows'), L('Categorie verticali', 'Vertical categories')], [L('Pivot: Valori', 'Pivot: Values'), L('Cosa calcolare', 'What to compute')], [L('Grafico a barre', 'Bar chart'), L('Confrontare categorie', 'Compare categories')], [L('Grafico a linee', 'Line chart'), L('Andamento nel tempo', 'Trend over time')]], L('Dai dati alle risposte.', 'From data to answers.')),
            dFlash(pFlash(), [[L('Una tabella estende da sola le formule', 'A table extends formulas by itself'), true], [L('Le celle unite aiutano le tabelle pivot', 'Merged cells help pivot tables'), false], [L('Un grafico pivot si aggiorna con i filtri', 'A pivot chart updates with filters'), true], [L('La torta è ideale per 20 categorie', 'A pie is ideal for 20 categories'), false]], L('Riassumere e mostrare.', 'Summarise and show.')),
        ]),
        lesson('dynamic', L('Matrici dinamiche e funzioni logiche', 'Dynamic arrays and logical functions'), [
            P('Le **matrici dinamiche** restituiscono più risultati da una sola formula, che si “espandono” nelle celle vicine. `FILTRO` estrae le righe che rispettano una condizione, `ORDINA` le mette in ordine, `UNICI` toglie i doppioni.', '**Dynamic arrays** return many results from one formula, which “spill” into neighbouring cells. `FILTER` extracts rows meeting a condition, `SORT` puts them in order, `UNIQUE` removes duplicates.'),
            C('=FILTRO(A2:C100; C2:C100>1000)          righe con importo oltre 1000
=ORDINA(UNICI(B2:B100))                  clienti senza doppioni, in ordine
=SE.ERRORE(CERCA.X(E2;A:A;B:B);"—")      ricerca con valore di riserva
=SOMMA.PIÙ.SE(C:C;B:B;"Rossi";D:D;">=2026-01-01")', 'excel'),
            P('`SE.ERRORE` sostituisce un errore (`#N/D`, `#DIV/0!`) con un valore scelto; `SOMMA.PIÙ.SE` somma con più condizioni. Nelle versioni inglesi le funzioni si chiamano `FILTER`, `SORT`, `UNIQUE`, `IFERROR`, `SUMIFS` e il separatore è la virgola.', '`IFERROR` replaces an error (`#N/A`, `#DIV/0!`) with a chosen value; `SUMIFS` sums with several conditions. In Italian versions the functions are `FILTRO`, `ORDINA`, `UNICI`, `SE.ERRORE`, `SOMMA.PIÙ.SE` and the separator is the semicolon.'),
        ], [
            Q('dy1', L('Che cosa fa `UNICI` (UNIQUE)?', 'What does `UNIQUE` do?'), [L('Toglie i doppioni', 'Removes duplicates'), L('Conta le celle', 'Counts cells'), L('Ordina', 'Sorts'), L('Somma', 'Sums')], 0, L('Spesso insieme a ORDINA.', 'Often with SORT.')),
            Q('dy2', L('Che cosa fa `SE.ERRORE` (IFERROR)?', 'What does `IFERROR` do?'), [L('Sostituisce un errore con un valore', 'Replaces an error with a value'), L('Crea un errore', 'Creates an error'), L('Cancella la riga', 'Deletes the row'), L('Colora la cella', 'Colours the cell')], 0, L('Niente #N/D nei report.', 'No #N/A in reports.')),
            Q('dy3', L('Che cosa significa che una formula si “espande”?', 'What does it mean that a formula “spills”?'), [L('I risultati riempiono le celle vicine', 'Results fill neighbouring cells'), L('Diventa più lenta', 'It gets slower'), L('Si copia in un altro file', 'It copies to another file'), L('Dà errore', 'It errors')], 0, L('È una matrice dinamica.', 'It is a dynamic array.')),
        ], task('excel', L('Scrivi una formula che filtra `A2:C50` tenendo le righe dove `C2:C50` è maggiore di `100` (in italiano o in inglese).', 'Write a formula filtering `A2:C50` keeping rows where `C2:C50` is greater than `100` (in Italian or English).'), '', [re('^=\s*(FILTRO|FILTER)\(\s*A2:C50\s*[;,]\s*C2:C50\s*>\s*100\s*\)', L('Il filtro è giusto', 'The filter is right'))], '', '=FILTRO(A2:C50;C2:C50>100)'), [
            dMatch(pMatch(), [['FILTRO / FILTER', L('Righe con una condizione', 'Rows meeting a condition')], ['ORDINA / SORT', L('Mette in ordine', 'Puts in order')], ['UNICI / UNIQUE', L('Senza doppioni', 'No duplicates')], ['SE.ERRORE / IFERROR', L('Valore di riserva', 'Fallback value')], ['SOMMA.PIÙ.SE / SUMIFS', L('Somma con più condizioni', 'Sum with several conditions')]], L('Le funzioni moderne.', 'Modern functions.')),
            dFlash(pFlash(), [[L('Una sola formula FILTRO può riempire molte celle', 'One FILTER formula can fill many cells'), true], [L('Nella versione italiana il separatore è la virgola', 'In the Italian version the separator is the comma'), false], [L('SE.ERRORE nasconde #N/D', 'IFERROR hides #N/A'), true], [L('UNICI somma i valori', 'UNIQUE sums values'), false]], L('Excel dinamico.', 'Dynamic Excel.')),
        ]),
    ],
];
